linear-cryptanalysis.pseudocode:
def parity(x):
    return bin(x).count('1') % 2

def matsui_alg1(pairs, a, b, bias_positive=True):
    # 근사식: P·a ⊕ C·b = K·γ 가 확률 ½ + ε 로 성립
    t = 0
    for p, c in pairs:  # 기지 평문-암호문 쌍
        if parity(p & a) ^ parity(c & b) == 0:
            t += 1
    if (t > len(pairs) / 2) == bias_positive:
        return 0  # 키 비트 합 K·γ = 0 으로 추정
    return 1

linear-discriminant-analysis.pseudocode:
def fisher_lda_2class(X1, X2):
    # X1, X2: 클래스별 표본 벡터 목록
    m1, m2 = mean(X1), mean(X2)  # 클래스 평균
    Sw = scatter(X1, m1) + scatter(X2, m2)  # 클래스 내 산포
    w = solve(Sw, m1 - m2)  # w ∝ Sw^-1 (m1 - m2)
    threshold = dot(w, (m1 + m2) / 2)  # 투영 평균의 중점
    return w, threshold

def scatter(X, m):
    return sum(outer(x - m, x - m) for x in X)

def classify(x, w, threshold):
    return 1 if dot(w, x) > threshold else 2

linear-probing.pseudocode:
def insert(T, key):
    m = len(T)
    i = h(key) % m  # 홈 주소
    for _ in range(m):
        if T[i] is None or T[i] == key:
            T[i] = key
            return i
        i = (i + 1) % m  # 바로 다음 버킷
    raise TableFull()

def search(T, key):
    m = len(T)
    i = h(key) % m
    for _ in range(m):
        if T[i] is None:  # 빈 칸 → 키 없음
            return -1
        if T[i] == key:
            return i
        i = (i + 1) % m
    return -1
# 삭제는 빈 칸 대신 삭제 표시(tombstone) 사용

linear-programming.pseudocode:
def simplex(c, A, b):  # max cx, Ax <= b, x >= 0 (b >= 0)
    m, n = len(A), len(c)
    # 표: [A | 여유변수 I | b], 마지막 행 = 목적함수
    T = [A[i] + [int(i == j) for j in range(m)] + [b[i]]
         for i in range(m)]
    T.append([-v for v in c] + [0] * (m + 1))
    basis = list(range(n, n + m))  # 초기 기저 = 여유변수
    while True:
        col = min(range(n + m), key=lambda j: T[-1][j])
        if T[-1][col] >= 0:
            break  # 음의 계수 없음 → 최적
        rows = [i for i in range(m) if T[i][col] > 0]
        if not rows:
            return None  # 무한해(unbounded)
        r = min(rows, key=lambda i: T[i][-1] / T[i][col])
        R = T[r] = [v / T[r][col] for v in T[r]]  # 최소비 피벗
        for i in range(m + 1):
            if i != r:  # 피벗 열을 0으로 소거
                f = T[i][col]
                T[i] = [a - f * q for a, q in zip(T[i], R)]
        basis[r] = col
    x = [0.0] * n
    for i, j in enumerate(basis):
        if j < n:
            x[j] = T[i][-1]
    return x, T[-1][-1]  # 최적해, 최적값

linked-list.pseudocode:
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def insert_after(prev, data):  # 위치를 알면 O(1)
    node = Node(data)
    node.next = prev.next  # 새 노드가 뒤 노드를 가리킴
    prev.next = node  # 앞 노드가 새 노드를 가리킴

def delete_after(prev):  # O(1)
    target = prev.next
    if target is not None:
        prev.next = target.next  # 링크 우회

def search(head, key):  # 순차 접근 O(n)
    cur = head
    while cur is not None and cur.data != key:
        cur = cur.next
    return cur

liquidity-pool.pseudocode:
class Pool:  # 상수곱 AMM(x·y = k)
    def __init__(self, x, y, fee=0.003):
        self.x, self.y, self.fee = x, y, fee  # 토큰 잔고

    def swap_a_for_b(self, dx):
        dx_eff = dx * (1 - self.fee)  # 수수료 제외분
        k = self.x * self.y
        dy = self.y - k / (self.x + dx_eff)  # k 유지
        self.x += dx  # 수수료는 풀에 남아 LP 몫
        self.y -= dy
        return dy  # 거래 클수록 슬리피지 증가

    def price_a(self):
        return self.y / self.x  # A 1개당 B 가격
